//! The enclosure family exercised end to end through provider
//! dispatch: `enclosureWitnessValid` — Lean-anchored goldens (the
//! kernel-decided accept examples, whose caps all sit EXACTLY at the
//! tail bound), named data mutants (every mutant flips a verdict),
//! refusal classes, and the frozen cross-implementation corpus replay
//! (`fixtures/enclosure_pyref_corpus.json`, generated by the
//! independent python reference `fixtures/enclosure_pyref_gen.py`,
//! whose tail arithmetic uses direct rational division where the
//! evaluator cross-multiplies — two arithmetic paths, one verdict).
//!
//! The test-side row emitter shares no code with the evaluator: it
//! writes `Op::Funa` field rows directly from the synthetic
//! declaration index.

mod common;

use common::{ev_elems, stack, STACK};
use geolog_envelope::body::Op;
use geolog_envelope::{ElemRef, Literal, Value};
use qtsl_geolog_provider::rowctx::CertRows;
use serde_json::Value as J;

const OWN: [u8; 32] = [0xE2; 32];

fn xref(name: &str) -> ElemRef {
    let c = stack()
        .fun(name)
        .unwrap_or_else(|| panic!("stack fun `{name}`"))
        .chid;
    assert_eq!(c.0, STACK, "chid homed in the stack revision");
    ElemRef::External {
        dep_index: 0,
        counter: c.1,
    }
}

fn lref(e: u32) -> Value {
    Value::Ref(ElemRef::Local(e))
}

fn natv(n: u64) -> Value {
    Value::Lit(Literal::nat(n))
}

fn qv(num: i64, den: u64) -> Value {
    Value::Lit(Literal::q(num, den).expect("canonical Q"))
}

/// Emit one judgment element: field rows for whichever of the four
/// fields are given (`None` = leave the row out — the refusal
/// battery's lever).
fn judgment_rows(
    func: Option<Value>,
    n: Option<Value>,
    r: Option<Value>,
    cap: Option<Value>,
) -> (u32, CertRows) {
    let j: u32 = 0;
    let mut ops = Vec::new();
    let mut field = |name: &str, v: Option<Value>| {
        if let Some(v) = v {
            ops.push(Op::Funa {
                fun: xref(name),
                args: vec![lref(j)],
                value: v,
            });
        }
    };
    field("EncJudgment/func", func);
    field("EncJudgment/n", n);
    field("EncJudgment/r", r);
    field("EncJudgment/cap", cap);
    (j, CertRows::from_ops(&ops, OWN, &[STACK]))
}

/// The four-field happy path.
fn judgment(func: u64, n: u64, r: (i64, u64), cap: (i64, u64)) -> (u32, CertRows) {
    judgment_rows(
        Some(natv(func)),
        Some(natv(n)),
        Some(qv(r.0, r.1)),
        Some(qv(cap.0, cap.1)),
    )
}

fn ev_j(rows: &(u32, CertRows)) -> Result<bool, String> {
    ev_elems("enclosureWitnessValid", &[rows.0], &rows.1)
}

// ---------------------------------------------------------------------
// Lean-anchored goldens (Enclosure.lean's kernel-decided examples)
// ---------------------------------------------------------------------

#[test]
fn golden_sin7_holds_exactly_at_the_bound() {
    // encCheck ⟨.sin, 7, 1, 1/35840, …⟩ = true — and tail(7, 1) is
    // exactly 1/35840, so this pins the <= boundary itself.
    assert_eq!(ev_j(&judgment(1, 7, (1, 1), (1, 35840))), Ok(true));
}

#[test]
fn golden_exp4_holds_exactly_at_the_bound() {
    // encCheck ⟨.exp, 4, 1/2, 1/3520, …⟩ = true; tail(4, 1/2) = 1/3520.
    assert_eq!(ev_j(&judgment(0, 4, (1, 2), (1, 3520))), Ok(true));
}

#[test]
fn golden_cos6_holds_exactly_at_the_bound() {
    // encCheck ⟨.cos, 6, 1, 1/4410, …⟩ = true; tail(6, 1) = 1/4410.
    assert_eq!(ev_j(&judgment(2, 6, (1, 1), (1, 4410))), Ok(true));
}

#[test]
fn golden_zero_radius_zero_cap_holds() {
    // tail(n, 0) = 0: the zero-radius witness needs no slack at all.
    assert_eq!(ev_j(&judgment(0, 0, (0, 1), (0, 1))), Ok(true));
}

// ---------------------------------------------------------------------
// Named data mutants — each flips a golden's verdict
// ---------------------------------------------------------------------

#[test]
fn mutant_tail_lie_fails() {
    // The Lean reject example: sin7's cap lowered to 1/40000, below
    // tail(7, 1) = 1/35840 (the wire battery's `EncTailLie`).
    assert_eq!(ev_j(&judgment(1, 7, (1, 1), (1, 40000))), Ok(false));
}

#[test]
fn mutant_radius_overrun_fails() {
    // The Lean reject example: sin7's radius raised to 9 = n + 2 —
    // the strict geometric guard's edge (the wire battery's
    // `EncRadiusOverrun`).
    assert_eq!(ev_j(&judgment(1, 7, (9, 1), (1, 35840))), Ok(false));
}

#[test]
fn mutant_negative_radius_fails() {
    assert_eq!(ev_j(&judgment(0, 4, (-1, 2), (1, 3520))), Ok(false));
}

#[test]
fn mutant_cap_one_hair_below_fails() {
    // exp4's cap scaled by (1 - 10^-9): the boundary is inclusive
    // from above and exclusive below, exactly.
    assert_eq!(
        ev_j(&judgment(0, 4, (1, 2), (999_999_999, 3_520_000_000_000))),
        Ok(false)
    );
}

#[test]
fn tag_is_not_the_deciding_content() {
    // The tail majorant is the uniform |a_k| <= 1/k! bound: once the
    // tag is representable, the decided verdict depends only on
    // (n, r, cap). All three tags agree on a hold and on a fail.
    for tag in 0..=2 {
        assert_eq!(ev_j(&judgment(tag, 7, (1, 1), (1, 35840))), Ok(true));
        assert_eq!(ev_j(&judgment(tag, 7, (1, 1), (1, 40000))), Ok(false));
    }
}

// ---------------------------------------------------------------------
// Refusal classes — undecidable or unrepresentable, never guessed
// ---------------------------------------------------------------------

#[test]
fn refusal_unknown_function_tag() {
    // The witness type has three inhabitants; the wire format rejects
    // a fourth tag at parse. No representable witness — refusal, not
    // a decided false.
    let err = ev_j(&judgment(3, 7, (1, 1), (1, 35840))).unwrap_err();
    assert!(err.contains("three-tag function roster"), "got: {err}");
}

#[test]
fn refusal_missing_field_row() {
    let rows = judgment_rows(Some(natv(1)), Some(natv(7)), None, Some(qv(1, 35840)));
    let err = ev_j(&rows).unwrap_err();
    assert!(err.contains("no `EncJudgment/r` row"), "got: {err}");
}

#[test]
fn refusal_conflicting_field_rows() {
    // Two `EncJudgment/n` rows — even agreeing multiplicity refuses
    // (never picking); these disagree.
    let (j, _) = judgment(1, 7, (1, 1), (1, 35840));
    let mut ops = Vec::new();
    for (name, v) in [
        ("EncJudgment/func", natv(1)),
        ("EncJudgment/n", natv(7)),
        ("EncJudgment/n", natv(8)),
        ("EncJudgment/r", qv(1, 1)),
        ("EncJudgment/cap", qv(1, 35840)),
    ] {
        ops.push(Op::Funa {
            fun: xref(name),
            args: vec![lref(j)],
            value: v,
        });
    }
    let rows = CertRows::from_ops(&ops, OWN, &[STACK]);
    let err = ev_elems("enclosureWitnessValid", &[j], &rows).unwrap_err();
    assert!(err.contains("multiple `EncJudgment/n` rows"), "got: {err}");
}

#[test]
fn refusal_degree_beyond_budget() {
    use qtsl_geolog_provider::enclosure::ENC_MAX_DEGREE;
    let err = ev_j(&judgment(0, ENC_MAX_DEGREE + 1, (1, 1), (1, 1))).unwrap_err();
    assert!(err.contains("degree budget"), "got: {err}");
    // At the budget itself: evaluates (decided, not refused).
    assert_eq!(ev_j(&judgment(0, ENC_MAX_DEGREE, (1, 1), (1, 1))), Ok(true));
}

#[test]
fn refusal_non_nat_tag_literal() {
    let rows = judgment_rows(
        Some(qv(1, 1)), // a Q literal where a Nat belongs
        Some(natv(7)),
        Some(qv(1, 1)),
        Some(qv(1, 35840)),
    );
    let err = ev_j(&rows).unwrap_err();
    assert!(err.contains("not a Nat literal"), "got: {err}");
}

#[test]
fn refusal_non_q_radius_literal() {
    let rows = judgment_rows(
        Some(natv(1)),
        Some(natv(7)),
        Some(natv(1)), // a Nat literal where a Q belongs
        Some(qv(1, 35840)),
    );
    let err = ev_j(&rows).unwrap_err();
    assert!(err.contains("not a Q literal"), "got: {err}");
}

#[test]
fn refusal_external_judgment_ref() {
    let (_, rows) = judgment(1, 7, (1, 1), (1, 35840));
    let ext = Value::Ref(ElemRef::External {
        dep_index: 0,
        counter: 999,
    });
    let err = common::ev("enclosureWitnessValid", &[&ext], &rows).unwrap_err();
    assert!(err.contains("external element ref"), "got: {err}");
}

// ---------------------------------------------------------------------
// The frozen cross-implementation corpus
// ---------------------------------------------------------------------

#[test]
fn corpus_replay() {
    let raw = include_str!("fixtures/enclosure_pyref_corpus.json");
    let c: J = serde_json::from_str(raw).expect("corpus parses");
    let cases = c["cases"].as_array().expect("cases");
    let counts = &c["counts"];
    assert_eq!(
        counts["total"].as_u64().expect("total") as usize,
        cases.len()
    );

    let mut holds = 0u64;
    for case in cases {
        let tag = case["tag"].as_u64().expect("tag");
        let n = case["n"].as_u64().expect("n");
        let q = |v: &J| -> (i64, u64) {
            let a = v.as_array().expect("rational pair");
            (
                a[0].as_i64().expect("numerator"),
                a[1].as_u64().expect("denominator"),
            )
        };
        let r = q(&case["r"]);
        let cap = q(&case["cap"]);
        let expected = case["verdict"].as_bool().expect("verdict");
        holds += expected as u64;
        assert_eq!(
            ev_j(&judgment(tag, n, r, cap)),
            Ok(expected),
            "corpus divergence at tag={tag} n={n} r={r:?} cap={cap:?}"
        );
    }
    assert_eq!(holds, counts["holds"].as_u64().expect("holds"));
}
